import{_ as e,c as t,o as r,a2 as i}from"./chunks/framework.CIiVzG-O.js";const c=JSON.parse('{"title":"服务条款","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/terms.md","filePath":"zh-CN/guide/terms.md","lastUpdated":1793163976000}'),o={name:"zh-CN/guide/terms.md"};function h(l,a,p,d,n,s){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="服务条款" tabindex="-1">服务条款 <a class="header-anchor" href="#服务条款" aria-label="Permalink to &quot;服务条款&quot;">​</a></h1><p>本条款管理你对 NueZip 的使用。下载、安装或使用 NueZip，即表示你同意本条款。如果你不同意，请勿使用该应用。</p><h2 id="许可与使用" tabindex="-1">许可与使用 <a class="header-anchor" href="#许可与使用" aria-label="Permalink to &quot;许可与使用&quot;">​</a></h2><p>NueZip 根据每个发布版本附带的许可条款提供。你被授予一项有限的、非独占的、不可转让的许可，可依据许可条款在你的 Mac 上使用本应用。</p><h2 id="仅本地运行" tabindex="-1">仅本地运行 <a class="header-anchor" href="#仅本地运行" aria-label="Permalink to &quot;仅本地运行&quot;">​</a></h2><p>NueZip 是一款完全离线的应用。所有归档操作都在你的设备上本地执行。没有任何文件、元数据或个人数据被传输到外部服务器。</p><h2 id="购买" tabindex="-1">购买 <a class="header-anchor" href="#购买" aria-label="Permalink to &quot;购买&quot;">​</a></h2><p>完整功能许可证可通过 Mac App Store 的一次性购买获得。所有购买均由 Apple 处理。NueZip 不处理支付信息。支持重新安装时的购买恢复。</p><h2 id="用户责任" tabindex="-1">用户责任 <a class="header-anchor" href="#用户责任" aria-label="Permalink to &quot;用户责任&quot;">​</a></h2><ul><li>合法使用 NueZip，并遵守适用规则。</li><li>不要试图反编译、逆向工程或以违反许可的方式修改应用。</li><li>不要使用 NueZip 来绕过归档上的版权保护或 DRM。</li></ul><h2 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to &quot;隐私&quot;">​</a></h2><p>有关数据实践和隐私的信息，请参阅 <a href="/zh-CN/guide/privacy.html">隐私政策</a>。</p><h2 id="无担保" tabindex="-1">无担保 <a class="header-anchor" href="#无担保" aria-label="Permalink to &quot;无担保&quot;">​</a></h2><p>NueZip 按 &quot;现状&quot; 提供，不附带任何担保。在法律允许的最大范围内，维护者放弃所有明示、暗示、法定或其他形式的担保，包括适销性和特定用途适用性。</p><h2 id="责任限制" tabindex="-1">责任限制 <a class="header-anchor" href="#责任限制" aria-label="Permalink to &quot;责任限制&quot;">​</a></h2><p>在法律允许的最大范围内，维护者不对因你使用该应用而产生的任何间接、偶然、特殊、后果性或惩罚性损害承担责任。</p><h2 id="终止" tabindex="-1">终止 <a class="header-anchor" href="#终止" aria-label="Permalink to &quot;终止&quot;">​</a></h2><p>如果你未能遵守本条款，授予你的权利将自动终止。</p><h2 id="变更" tabindex="-1">变更 <a class="header-anchor" href="#变更" aria-label="Permalink to &quot;变更&quot;">​</a></h2><p>我们可能会不时更新本条款。变更后继续使用即视为接受修订后的条款。</p><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><p>有关本条款的问题，请在项目仓库提交 issue： <code>https://github.com/nuezip/nuezip/issues</code></p><p>或通过电子邮件联系我们：nuezip@w3cub.com</p><p><em>最后更新：2026 年 6 月 14 日</em></p>',24)])])}const m=e(o,[["render",h]]);export{c as __pageData,m as default};
